CREATE OR REPLACE FUNCTION public.configuration_merge_supplier(p_source_id uuid, p_destination_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$ declare v_owner uuid := private.app_workspace_owner_id(); v_source public.suppliers%rowtype; v_destination public.suppliers%rowtype; v_actor uuid := auth.uid(); v_actor_email text; v_invoice_count integer := 0; v_history_count integer := 0; v_product_count integer := 0; v_relation_count integer := 0; v_alias_count integer := 0; v_relation record; v_destination_relation uuid; begin if v_owner is null or auth.uid() is null or not coalesce(private.app_is_admin(),false) then raise exception 'Solo un administrador puede fusionar proveedores.'; end if; if p_source_id is null or p_destination_id is null or p_source_id=p_destination_id then raise exception 'El proveedor origen y destino deben ser distintos.'; end if; select * into v_source from public.suppliers where id=p_source_id and owner_id=v_owner for update; if not found then raise exception 'Proveedor origen no encontrado en este workspace.'; end if; select * into v_destination from public.suppliers where id=p_destination_id and owner_id=v_owner for update; if not found then raise exception 'Proveedor destino no encontrado en este workspace.'; end if; if nullif(regexp_replace(upper(coalesce(v_source.tax_id,'')),'[^A-Z0-9]','','g'),'') is not null and nullif(regexp_replace(upper(coalesce(v_destination.tax_id,'')),'[^A-Z0-9]','','g'),'') is not null and regexp_replace(upper(v_source.tax_id),'[^A-Z0-9]','','g') <> regexp_replace(upper(v_destination.tax_id),'[^A-Z0-9]','','g') then raise exception 'Los proveedores tienen identificaciones fiscales diferentes. Revisa la fusión manualmente.'; end if; perform 1 from public.supplier_products where owner_id=v_owner and supplier_id=p_source_id order by id for update; perform 1 from public.invoices where owner_id=v_owner and supplier_id=p_source_id order by id for update; if exists(select 1 from public.invoices where supplier_id=p_source_id and owner_id is distinct from v_owner) or exists(select 1 from public.products where last_supplier_id=p_source_id and owner_id is distinct from v_owner) or exists(select 1 from public.product_price_history where supplier_id=p_source_id and owner_id is distinct from v_owner) or exists(select 1 from public.supplier_products where supplier_id=p_source_id and owner_id is distinct from v_owner) or exists( select 1 from public.invoice_lines l join public.supplier_products sp on sp.id=l.supplier_product_id where sp.owner_id=v_owner and sp.supplier_id=p_source_id and l.owner_id is distinct from v_owner ) or exists( select 1 from public.invoice_lines l join public.invoices i on i.id=l.invoice_id where i.owner_id=v_owner and i.supplier_id=p_source_id and l.owner_id is distinct from v_owner ) or exists( select 1 from public.product_price_history h join public.invoices i on i.id=h.invoice_id where i.owner_id=v_owner and i.supplier_id=p_source_id and h.owner_id is distinct from v_owner ) then raise exception 'La fusión contiene referencias de otro workspace; revisa la integridad antes de continuar.' using errcode='42501'; end if; if exists( select 1 from public.invoices s join public.invoices d on d.owner_id=v_owner and d.supplier_id=p_destination_id and d.invoice_number=s.invoice_number where s.owner_id=v_owner and s.supplier_id=p_source_id and s.invoice_number is not null and length(trim(s.invoice_number))>0 ) then raise exception 'La fusión produciría facturas duplicadas con el mismo número. No se ha modificado ningún dato.'; end if; select count(*) into v_invoice_count from public.invoices where owner_id=v_owner and supplier_id=p_source_id; select count(*) into v_history_count from public.product_price_history where owner_id=v_owner and supplier_id=p_source_id; select count(*) into v_product_count from public.products where owner_id=v_owner and last_supplier_id=p_source_id; select count(*) into v_relation_count from public.supplier_products where owner_id=v_owner and supplier_id=p_source_id; select count(*) into v_alias_count from public.entity_alias_rules where owner_id=v_owner and entity_type='supplier' and target_entity_id=p_source_id; update public.suppliers set tax_id=coalesce(nullif(trim(v_destination.tax_id),''),v_source.tax_id), email=coalesce(nullif(trim(v_destination.email),''),v_source.email), phone=coalesce(nullif(trim(v_destination.phone),''),v_source.phone), address=coalesce(nullif(trim(v_destination.address),''),v_source.address), website=coalesce(nullif(trim(v_destination.website),''),v_source.website), default_category_id=coalesce(v_destination.default_category_id,v_source.default_category_id), notes=case when nullif(trim(coalesce(v_destination.notes,'')),'') is null then v_source.notes when nullif(trim(coalesce(v_source.notes,'')),'') is null then v_destination.notes when position(v_source.notes in v_destination.notes)>0 then v_destination.notes else v_destination.notes || E'\n' || v_source.notes end where id=p_destination_id and owner_id=v_owner; for v_relation in select id,supplier_description from public.supplier_products where owner_id=v_owner and supplier_id=p_source_id order by id loop select id into v_destination_relation from public.supplier_products where owner_id=v_owner and supplier_id=p_destination_id and supplier_description=v_relation.supplier_description limit 1; if v_destination_relation is not null then update public.invoice_lines set supplier_product_id=v_destination_relation where supplier_product_id=v_relation.id and owner_id=v_owner; delete from public.supplier_products where id=v_relation.id and owner_id=v_owner; end if; v_destination_relation := null; end loop; update public.supplier_products set supplier_id=p_destination_id where owner_id=v_owner and supplier_id=p_source_id; update public.invoices set supplier_id=p_destination_id where owner_id=v_owner and supplier_id=p_source_id; update public.product_price_history set supplier_id=p_destination_id where owner_id=v_owner and supplier_id=p_source_id; update public.products set last_supplier_id=p_destination_id where owner_id=v_owner and last_supplier_id=p_source_id; update public.entity_alias_rules set target_entity_id=p_destination_id where owner_id=v_owner and entity_type='supplier' and target_entity_id=p_source_id; delete from public.suppliers where id=p_source_id and owner_id=v_owner; select email into v_actor_email from public.app_users where user_id=v_actor limit 1; insert into public.audit_logs( workspace_owner_id,actor_user_id,actor_email,module,action, entity_type,entity_id,entity_label,summary,details ) values ( v_owner,v_actor,v_actor_email,'settings','merge','suppliers', p_destination_id::text,v_destination.name, 'Fusionó proveedor '||v_source.name||' en '||v_destination.name, jsonb_build_object( 'source_id',p_source_id,'destination_id',p_destination_id, 'source_name',v_source.name,'destination_name',v_destination.name, 'affected',jsonb_build_object( 'invoices',v_invoice_count,'price_history',v_history_count, 'products',v_product_count,'supplier_products',v_relation_count, 'aliases',v_alias_count ) ) ); return jsonb_build_object( 'ok',true,'sourceId',p_source_id,'destinationId',p_destination_id, 'affected',jsonb_build_object( 'invoices',v_invoice_count,'priceHistory',v_history_count, 'products',v_product_count,'supplierProducts',v_relation_count, 'aliases',v_alias_count ) ); end; $function$; CREATE OR REPLACE FUNCTION public.configuration_rebuild_price_history_links(p_apply boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$ declare v_owner uuid := private.app_workspace_owner_id(); v_actor uuid := auth.uid(); v_actor_email text; v_missing integer := 0; v_mismatched integer := 0; v_written integer := 0; begin if v_owner is null or auth.uid() is null or not coalesce(private.app_is_admin(),false) then raise exception 'Solo un administrador puede reconstruir el histórico de precios.'; end if; if p_apply and exists( select 1 from public.invoice_lines l join public.invoices i on i.id=l.invoice_id and i.owner_id=v_owner join public.products p on p.id=l.product_id and p.owner_id=v_owner join public.product_price_history h on h.invoice_line_id=l.id where l.owner_id=v_owner and l.normalized_unit_price is not null and h.owner_id is distinct from v_owner ) then raise exception 'El histórico contiene referencias de otro workspace; revisa la integridad antes de continuar.' using errcode='42501'; end if; with candidates as ( select l.id as invoice_line_id,l.product_id,i.supplier_id,i.id as invoice_id, coalesce(i.issue_date,i.received_date) as price_date, l.unit_price,l.normalized_unit_price, coalesce(p.base_unit,l.unit,'ud') as base_unit, coalesce(i.currency,'EUR') as currency from public.invoice_lines l join public.invoices i on i.id=l.invoice_id and i.owner_id=v_owner join public.products p on p.id=l.product_id and p.owner_id=v_owner where l.owner_id=v_owner and l.product_id is not null and l.normalized_unit_price is not null ) select count(*) filter (where h.id is null), count(*) filter ( where h.id is not null and ( h.product_id is distinct from c.product_id or h.supplier_id is distinct from c.supplier_id or h.invoice_id is distinct from c.invoice_id or h.price_date is distinct from c.price_date or h.normalized_unit_price is distinct from c.normalized_unit_price or h.base_unit is distinct from c.base_unit or h.currency is distinct from c.currency ) ) into v_missing,v_mismatched from candidates c left join public.product_price_history h on h.owner_id=v_owner and h.invoice_line_id=c.invoice_line_id; if not p_apply then return jsonb_build_object( 'ok',true,'preview',true, 'missing',v_missing,'mismatched',v_mismatched, 'historicalRowsDeleted',0 ); end if; with candidates as ( select l.id as invoice_line_id,l.product_id,i.supplier_id,i.id as invoice_id, coalesce(i.issue_date,i.received_date) as price_date, l.unit_price,l.normalized_unit_price, coalesce(p.base_unit,l.unit,'ud') as base_unit, coalesce(i.currency,'EUR') as currency from public.invoice_lines l join public.invoices i on i.id=l.invoice_id and i.owner_id=v_owner join public.products p on p.id=l.product_id and p.owner_id=v_owner where l.owner_id=v_owner and l.product_id is not null and l.normalized_unit_price is not null ), written as ( insert into public.product_price_history( owner_id,product_id,supplier_id,invoice_id,invoice_line_id,price_date, purchase_unit_price,normalized_unit_price,base_unit,currency ) select v_owner,product_id,supplier_id,invoice_id,invoice_line_id,price_date, unit_price,normalized_unit_price,base_unit,currency from candidates on conflict(invoice_line_id) do update set product_id=excluded.product_id, supplier_id=excluded.supplier_id, invoice_id=excluded.invoice_id, price_date=excluded.price_date, purchase_unit_price=excluded.purchase_unit_price, normalized_unit_price=excluded.normalized_unit_price, base_unit=excluded.base_unit, currency=excluded.currency where product_price_history.owner_id=excluded.owner_id returning id ) select count(*) into v_written from written; select email into v_actor_email from public.app_users where user_id=v_actor limit 1; insert into public.audit_logs( workspace_owner_id,actor_user_id,actor_email,module,action, entity_type,entity_id,entity_label,summary,details ) values ( v_owner,v_actor,v_actor_email,'settings','rebuild','product_price_history', null,null, 'Reconstruyó enlaces del histórico de precios desde líneas de factura', jsonb_build_object( 'rows_written',v_written,'missing_before',v_missing, 'mismatched_before',v_mismatched,'historical_rows_deleted',0 ) ); return jsonb_build_object( 'ok',true,'preview',false, 'rowsWritten',v_written,'missingBefore',v_missing,'mismatchedBefore',v_mismatched, 'historicalRowsDeleted',0 ); end; $function$; 
